import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("Files in archive:", names)
    shared = None
    if 'xl/sharedStrings.xml' in names:
        shared = z.read('xl/sharedStrings.xml')
    sheet = z.read('xl/worksheets/sheet1.xml')

def parse_shared(xml_bytes):
    if xml_bytes is None:
        return {}
    root = ET.fromstring(xml_bytes)
    items = []
    for si in root.findall('m:si', NS):
        text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        items.append(text)
    return items

shared_items = parse_shared(shared)

root = ET.fromstring(sheet)
rows = []
for row in root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
    row_data = {}
    for c in row.findall('m:c', NS):
        ref = c.get('r')
        t = c.get('t')
        v = c.find('m:v', NS)
        val = v.text if v is not None else None
        if t == 's' and val is not None:
            val = shared_items[int(val)]
        row_data[ref] = val
    rows.append(row_data)

# Print all cells with values
for r in rows:
    print(r)

import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
TAG = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    shared_items = []
    if 'xl/sharedStrings.xml' in names:
        sroot = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in sroot.findall(TAG + 'si'):
            text = ''.join(t.text or '' for t in si.iter(TAG + 't'))
            shared_items.append(text)
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

for row in root.iter(TAG + 'row'):
    row_data = {}
    for c in row.findall(TAG + 'c'):
        ref = c.get('r')
        t = c.get('t')
        v = c.find(TAG + 'v')
        val = None
        if t == 's' and v is not None:
            val = shared_items[int(v.text)]
        elif t == 'inlineStr':
            is_el = c.find(TAG + 'is')
            if is_el is not None:
                val = ''.join(x.text or '' for x in is_el.iter(TAG + 't'))
        elif v is not None:
            val = v.text
        row_data[ref] = val
    if any(x is not None for x in row_data.values()):
        print(row_data)

